/** يحمّل نسخة WebP مصغرة ومخزنة مؤقتاً بدلاً من الصورة الأصلية الكبيرة. */
function fixImageUrl(url: string, width = 640): string {
  if (!url) return FALLBACK_IMG;
  if (url.startsWith("data:")) return url;
  const source = url.replace(/^http:\/\//i, "https://");

  // Imgur provides cached thumbnail variants from its own CDN. This avoids
  // downloading multi-megabyte originals for small cards.
  const imgur = source.match(/^https:\/\/i\.imgur\.com\/([^./]+)\.(jpe?g|png)$/i);
  if (imgur) {
    const suffix = width <= 160 ? "t" : width <= 400 ? "m" : width <= 700 ? "l" : "h";
    return `https://i.imgur.com/${imgur[1]}${suffix}.${imgur[2]}`;
  }

  return `https://wsrv.nl/?url=${encodeURIComponent(source)}&w=${width}&output=webp&q=76&fit=inside`;
}

